const { seg, lerp, eo, ei, eio, eob, clamp01, TextFx } = kit;
Object.assign(W, {
  // The cup, drawn round (0,0) at the middle of its rim and lit from the left. Its coffee is one ellipse a scene raises
  // behind the rim, with two rings a scene spreads where the stream lands.
  cup(cls) {
    const body = 'M-220 0 C-220 150 -168 240 -104 244 H104 C168 240 220 150 220 0 Z';
    return '<g class="' + cls + '"><defs><linearGradient id="' + cls + '-glaze"><stop offset="0" style="stop-color:var(--clay)"/><stop offset=".5" style="stop-color:var(--accent)"/><stop offset="1" style="stop-color:var(--clay-shade)"/></linearGradient>' +
      '<clipPath id="' + cls + '-body"><path d="' + body + '"/></clipPath><clipPath id="' + cls + '-mouth"><ellipse cx="0" cy="3" rx="203" ry="37"/></clipPath></defs>' +
      '<ellipse cx="46" cy="270" rx="372" ry="40" style="fill:rgba(0,0,0,.2)"/>' +
      '<ellipse cx="0" cy="254" rx="340" ry="50" style="fill:var(--fog)"/><ellipse cx="0" cy="244" rx="340" ry="48" style="fill:var(--ground)"/><ellipse cx="0" cy="246" rx="190" ry="24" style="fill:var(--fog)"/>' +
      '<path d="M196 50 C336 26 344 206 164 180" style="fill:none;stroke:var(--clay-shade);stroke-width:38;stroke-linecap:round"/><path d="M204 44 C318 30 322 178 190 168" style="fill:none;stroke:var(--accent);stroke-width:12;stroke-linecap:round"/>' +
      '<path d="' + body + '" fill="url(#' + cls + '-glaze)"/>' +
      '<g clip-path="url(#' + cls + '-body)"><path d="M-230 92 Q0 142 230 92 V124 Q0 174 -230 124 Z" style="fill:var(--ground)"/><path d="M-230 136 Q0 186 230 136 V144 Q0 194 -230 144 Z" style="fill:var(--ground);opacity:.55"/></g>' +
      '<path d="M-184 34 C-180 120 -152 190 -116 220" style="fill:none;stroke:var(--ground);stroke-width:9;opacity:.4;stroke-linecap:round"/>' +
      '<ellipse cx="0" cy="0" rx="220" ry="46" style="fill:var(--clay)"/><ellipse cx="0" cy="3" rx="203" ry="37" style="fill:var(--clay-shade)"/>' +
      '<g clip-path="url(#' + cls + '-mouth)"><g class="' + cls + '-coffee"><ellipse cx="0" cy="0" rx="210" ry="40" style="fill:var(--brew)"/><ellipse cx="0" cy="0" rx="196" ry="33" style="fill:none;stroke:var(--amber);stroke-width:5;opacity:.7"/>' +
      '<ellipse class="' + cls + '-ring" cx="14" cy="0" style="fill:none;stroke:var(--amber);stroke-width:5"/><ellipse class="' + cls + '-ring" cx="14" cy="0" style="fill:none;stroke:var(--amber);stroke-width:5"/></g></g></g>';
  },
});
kit.scene('pour', {
  init(kit) {
    const r = kit.rng(8);
    this.steam = W.steam(kit, 7, 1340, 612, 440);
    const beans = Array.from({ length: 6 }, (_, i) => {
      const x = 190 + i * 118 + r() * 50, y = 930 + r() * 90, a = (r() * 150 - 75).toFixed(0);
      return '<g transform="translate(' + x.toFixed(0) + ' ' + y.toFixed(0) + ') rotate(' + a + ')"><ellipse cx="4" cy="8" rx="36" ry="24" style="fill:rgba(0,0,0,.16)"/><ellipse rx="34" ry="23" style="fill:var(--brew)"/><path d="M-27 2 Q-6 -12 6 0 T27 -2" style="fill:none;stroke:var(--deep);stroke-width:4;stroke-linecap:round"/></g>';
    }).join('');
    kit.stage.append(kit.h('<div class="ground pour-room" style="background:var(--main);color:var(--ground)">' +
      '<svg class="art" viewBox="0 0 1920 1080"><g class="pour-light"><path d="M1010 150 L1330 110 V830 L1010 870 Z M1372 105 L1692 65 V785 L1372 825 Z" style="fill:var(--second);opacity:.2"/></g>' +
      '<g class="pour-table"><rect x="-40" y="842" width="2000" height="260" style="fill:var(--wood)"/><rect x="-40" y="842" width="2000" height="12" style="fill:var(--glow)"/><g class="pour-beans">' + beans + '</g></g>' +
      '<g class="pour-kettle"><path d="M2010 380 C1850 380 1800 170 1640 150 C1520 136 1452 196 1412 268" style="fill:none;stroke:var(--steel);stroke-width:44"/><path d="M2010 366 C1860 366 1812 160 1642 138 C1528 124 1456 180 1420 240" style="fill:none;stroke:var(--ground);stroke-width:7;opacity:.6;stroke-linecap:round"/></g>' +
      '<g class="pour-cup" transform="translate(1340 640) scale(1.28)">' + W.cup('pour-mug') + '</g>' +
      '<clipPath id="pour-above"><rect x="0" y="-200" width="1920" height="842"/><ellipse cx="1340" cy="644" rx="259" ry="47"/></clipPath>' +
      '<g clip-path="url(#pour-above)"><path class="pour-stream" pathLength="1" style="fill:none;stroke:var(--brew);stroke-width:20;stroke-linecap:round"/><path class="pour-shine" pathLength="1" transform="translate(-5 0)" style="fill:none;stroke:var(--amber);stroke-width:6;stroke-linecap:round"/></g>' +
      this.steam.markup + '</svg>' +
      '<div class="words" style="left:130px;top:210px;width:860px"><h2 class="line pour-line">Roasted at sunrise.</h2><p class="sub pour-sub">In small batches, for slow mornings.</p></div></div>'));
    const q = (s) => kit.stage.querySelector(s);
    this.steam.bind(q('.steam'));
    Object.assign(this, { light: q('.pour-light'), kettle: q('.pour-kettle'), stream: q('.pour-stream'), shine: q('.pour-shine'), cup: q('.pour-cup'),
      coffee: q('.pour-mug-coffee'), rings: [...kit.stage.querySelectorAll('.pour-mug-ring')], line: q('.pour-line'), sub: q('.pour-sub') });
  },
  render(t) {
    // The kettle tips in, pours from 0.55 s to 2.9 s, and lifts away; the coffee rises behind the rim meanwhile.
    const tip = eio(seg(t, 0, 0.6)) - eio(seg(t, 2.9, 3.6)), level = eio(seg(t, 0.8, 3.05)), cy = lerp(82, 4, level);
    this.kettle.setAttribute('transform', 'rotate(' + lerp(13, 0, tip).toFixed(2) + ' 2010 380)');
    const land = 640 + 1.28 * (cy - 6), sway = 5 * Math.sin(t * 5.2);
    const d = 'M1410 262 C1392 330 ' + (1362 + sway).toFixed(1) + ' 430 ' + (1358 + sway * 0.4).toFixed(1) + ' ' + land.toFixed(1);
    const on = seg(t, 0.5, 0.85), off = ei(seg(t, 2.9, 3.25));
    for (const path of [this.stream, this.shine]) {
      path.setAttribute('d', d);
      path.style.strokeDasharray = Math.max(0, on - off).toFixed(3) + ' 2';
      path.style.strokeDashoffset = (-off).toFixed(3);
      path.style.opacity = on > 0 && off < 1 ? 1 : 0;
    }
    this.coffee.setAttribute('transform', 'translate(0 ' + cy.toFixed(1) + ')');
    this.rings.forEach((ring, i) => {
      const q = (t * 1.3 + i / 2) % 1, pouring = seg(t, 0.85, 1.1) * (1 - seg(t, 3.2, 3.7));
      ring.setAttribute('rx', (24 + 150 * q).toFixed(1));
      ring.setAttribute('ry', (5 + 26 * q).toFixed(1));
      ring.style.opacity = ((1 - q) * 0.8 * pouring).toFixed(3);
    });
    // The cup takes the weight of the pour, and settles.
    const dip = 5 * (seg(t, 0.85, 1.2) - eob(seg(t, 3.2, 3.9), 1.7));
    this.cup.setAttribute('transform', 'translate(1340 ' + (640 + dip).toFixed(1) + ') scale(1.28)');
    this.steam.render(t, eio(seg(t, 2.5, 3.8)));
    this.light.style.transform = 'translateX(' + (-34 * t / 4.5).toFixed(1) + 'px)';
    this.light.style.opacity = (0.85 + 0.15 * Math.sin(t * 0.8)).toFixed(3);
    TextFx.fadeFromRight(this.line, t, 0.35);
    this.sub.style.opacity = eo(seg(t, 1.5, 2.1)).toFixed(3);
    this.sub.style.transform = 'translateX(' + ((1 - eo(seg(t, 1.5, 2.1))) * 26).toFixed(1) + 'px)';
  },
});
